mapper.select:
select * from ( select
(NVL(CLASS1_PLAN, 0) + NVL(CLASS2_PLAN, 0) + NVL(CLASS3_PLAN, 0)) as daily_total_qty, (NVL(CLASS1_PLAN_NUM, 0) + NVL(CLASS2_PLAN_NUM, 0) + NVL(CLASS3_PLAN_NUM, 0)) as daily_total_qty_num, b.MONTH_PLAN_QTY as month_plan, CEIL(b.MONTH_REMAIN_QTY) as month_plan_os, c.COLOR_TYPE, c.COLOR_CODE, d.notes, log.change_mid_plan, log.change_night_plan, log.change_day_plan from t_gdyy_schedule_result a LEFT JOIN ( select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY from T_GDYY_MONTH_PLAN_SURPLUS where YEAR=#{year,jdbcType=VARCHAR} and MONTH= #{month,jdbcType=VARCHAR} and del_flag = '0' ) b on a.BIG_ROLL_CODE=b.MATERIAL_CODE LEFT JOIN T_GDYY_BIG_ROLL_COLOR c ON a.BIG_ROLL_CODE = c.BIG_ROLL_CODE AND c.STATUS = '0' AND c.DEL_FLAG = '0' LEFT JOIN ( SELECT BIG_ROLL_CODE,listagg(notes,',') within group (order by notes) notes FROM T_GDYY_NOTE WHERE STATUS = '0' AND DEL_FLAG = '0' AND NVL(START_TIME, TO_DATE('0001-01-01', 'yyyy-MM-dd')) <= #{scheduleDate} AND NVL(END_TIME, TO_DATE('9999-12-31', 'yyyy-MM-dd')) >= #{scheduleDate} GROUP BY BIG_ROLL_CODE ) d ON d.BIG_ROLL_CODE = a.BIG_ROLL_CODE LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(decode(BEFORE_MID_PLAN, AFTER_MID_PLAN,0,1)) change_mid_plan, max(decode(BEFORE_NIGHT_PLAN, AFTER_NIGHT_PLAN,0,1)) change_night_plan, max(decode(BEFORE_DAY_PLAN, AFTER_DAY_PLAN,0,1)) change_day_plan FROM T_GDYY_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id where a.del_flag = '0' and a.schedule_date = #{scheduleDate}
and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and production_status = #{productionStatus} and a.is_release = #{isRelease} and a.id in #{scheduleId} order by a.CREATE_TIME desc ) t
order by ${orderStr}

select count(1)
from t_schedule_publish_record
where procedure_code = #{procedureCode,jdbcType=VARCHAR}
  and schedule_date = #{scheduleDate,jdbcType=DATE}
  and publish_status = '1'
  and del_flag = '0'

select count(1) from t_gdyy_schedule_result
where del_flag = '0'
and schedule_date = #{scheduleDate}
and big_roll_code = #{bigRollCode}
and id != #{id}

select count(1) from t_gdyy_schedule_result
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

mapper.update:
update t_gdyy_schedule_result
set IS_RELEASE = #{isRelease, jdbcType=VARCHAR}
,PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = sysdate
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

update t_gdyy_schedule_result set IS_RELEASE = #{status}
, PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = sysdate
where id in

    #{id}

update t_gdyy_schedule_result set del_flag = 1
where id in

    #{id}
